mapper.select:
SELECT skill.*
FROM organization_skill_installations installation
JOIN platform_skills skill ON skill.id = installation.skill_id
WHERE installation.organization_id = #{organizationId}
  AND skill.id = #{skillId}
  AND skill.status = 'active'

mapper.update:
UPDATE credential_handles SET name = COALESCE(#{name}, name), status = COALESCE(#{status}, status),
  metadata = COALESCE(#{metadata, typeHandler=com.kross.support.JsonbTypeHandler}, metadata), updated_at = now()
WHERE id = #{id}
